      'Bazı hücreleri karala. Odadaki sayı o odadaki kara hücre sayısıdır. Karalar yan yana değmez, beyazlar tek parça kalır. Düz bir beyaz şerit iki oda sınırını birden geçemez.',
      'Shade some cells. A number in a room is how many of its cells are black. Black cells never touch side by side and white cells stay connected. A straight run of white cells may not cross two room borders.',
      'Schwärze einige Felder. Die Zahl im Raum nennt seine schwarzen Felder. Schwarze berühren sich nicht seitlich, Weiße bleiben verbunden. Eine gerade weiße Reihe überquert nie zwei Raumgrenzen.',
      'Sombrea algunas casillas. El número de una sala indica sus negras. Las negras no se tocan de lado y las blancas quedan unidas. Una fila recta de blancas no cruza dos bordes de sala.',
      'Noircissez des cases. Le nombre d\'une pièce donne ses cases noires. Les noires ne se touchent pas par un côté et les blanches restent reliées. Une ligne droite de blanches ne traverse pas deux bords de pièce.',
      'ظلّل بعض الخانات. رقم الغرفة عدد خاناتها السوداء. لا تتجاور السوداوات، وتبقى البيضاوات متصلة. لا يعبر خط مستقيم من الأبيض حدّي غرفتين.',
      'چند خانه را سیاه کن. عدد اتاق تعداد خانه‌های سیاه آن است. سیاه‌ها پهلو به پهلو نیستند و سفیدها پیوسته‌اند. ردیف مستقیم سفید از دو مرز اتاق نمی‌گذرد.',
      'השחירו חלק מהמשבצות. מספר בחדר הוא כמות השחורות בו. שחורות לא נוגעות בצלע והלבנות מחוברות. רצף לבן ישר לא חוצה שני גבולות חדר.',
      'کچھ خانے سیاہ کریں۔ کمرے کا نمبر اس کے سیاہ خانے ہیں۔ سیاہ ساتھ نہیں لگتے، سفید جڑے رہتے ہیں۔ سیدھی سفید لڑی دو کمرہ سرحدیں پار نہیں کرتی۔',
      'Закрасьте часть клеток. Число в комнате — сколько в ней чёрных. Чёрные не соприкасаются сторонами, белые связаны. Прямой ряд белых не пересекает две границы комнат.',
      'Зафарбуйте частину клітинок. Число в кімнаті — скільки в ній чорних. Чорні не торкаються сторонами, білі зв\'язані. Прямий ряд білих не перетинає дві межі кімнат.',
      'Zaczernij część pól. Liczba w pokoju to jego czarne pola. Czarne nie stykają się bokami, białe są połączone. Prosty ciąg białych nie przekracza dwóch granic pokoi.',
      'Začerni některá pole. Číslo v pokoji udává jeho černá pole. Černá se nedotýkají stranou, bílá jsou spojená. Rovná řada bílých nepřekročí dvě hranice pokojů.',
      'Înnegrește unele celule. Numărul unei camere arată câte negre are. Negrele nu se ating lateral, albele rămân unite. Un șir drept de albe nu trece două margini de cameră.',
      'Feketíts be néhány mezőt. A szobában lévő szám a fekete mezői száma. Feketék oldalt nem érintkeznek, a fehérek összefüggők. Egyenes fehér sor nem lépi át két szoba határát.',
      'Μαύρισε κάποια κελιά. Ο αριθμός δωματίου δίνει τα μαύρα του. Τα μαύρα δεν ακουμπούν πλάι, τα λευκά ενωμένα. Ευθεία λευκών δεν περνά δύο όρια δωματίων.',
      'Annerisci alcune caselle. Il numero di una stanza indica le sue nere. Le nere non si toccano di lato, le bianche restano unite. Una fila dritta di bianche non attraversa due confini di stanza.',
      'Sombreie algumas casas. O número de uma sala indica as suas pretas. As pretas não se tocam de lado e as brancas ficam ligadas. Uma fila reta de brancas não cruza dois limites de sala.',
      'Kleur enkele vakjes zwart. Het getal in een kamer is het aantal zwarte. Zwarte raken elkaar niet zijdelings, witte blijven verbonden. Een rechte witte reeks kruist geen twee kamergrenzen.',
      'Svärta några rutor. Talet i ett rum anger dess svarta. Svarta rör inte varandra på sidan, vita hänger ihop. En rak rad vita korsar inte två rumsgränser.',
      'Sværtn nogle felter. Tallet i et rum angiver dets sorte. Sorte rører ikke hinanden på siden, hvide hænger sammen. En lige række hvide krydser ikke to rumgrænser.',
      'Svert noen ruter. Tallet i et rom angir dets svarte. Svarte berører ikke hverandre sideveis, hvite henger sammen. En rett rekke hvite krysser ikke to romgrenser.',
      'Varjosta ruutuja. Huoneen luku kertoo sen mustat. Mustat eivät kosketa sivuittain, valkoiset pysyvät yhtenäisinä. Suora valkoinen jono ei ylitä kahta huoneen rajaa.',
      'いくつかのマスを黒く塗ります。部屋の数字はその部屋の黒マス数。黒マスは辺で接さず、白マスはひとつながり。白マスの直線は部屋の境界を2本またげません。',
      '몇 칸을 검게 칠하세요. 방의 숫자는 그 방의 검은 칸 수입니다. 검은 칸은 맞닿지 않고 흰 칸은 이어집니다. 곧은 흰 줄은 방 경계를 두 번 넘지 못합니다.',
      '涂黑部分格子。房间中的数字为该房间黑格数。黑格不能边相邻，白格保持连通。连续的白格直线不能跨越两条房间边界。',
      'कुछ ख़ाने काले करें। कमरे का अंक उसमें काले ख़ाने है। काले बगल में नहीं सटते, सफ़ेद जुड़े रहते हैं। सीधी सफ़ेद पंक्ति दो कमरा-सीमाएँ पार नहीं करती।',
      'কিছু ঘর কালো করুন। কক্ষের সংখ্যা তার কালো ঘর। কালো পাশাপাশি ছোঁয় না, সাদা যুক্ত থাকে। সোজা সাদা সারি দুটি কক্ষ-সীমা পেরোয় না।',
