      'Schwärze einige Felder. Eine Zahl zählt die weißen Felder, die sie in vier Richtungen bis zu Schwarz oder Rand sieht, sich selbst eingeschlossen. Schwarze berühren sich nicht seitlich, Weiße bleiben verbunden.',
      'Sombrea algunas casillas. Un número cuenta las blancas visibles en cuatro direcciones hasta una negra o el borde, incluida ella. Las negras no se tocan de lado y las blancas quedan unidas.',
      'Noircissez des cases. Un nombre compte les blanches visibles dans quatre directions jusqu\'à une noire ou au bord, lui compris. Les noires ne se touchent pas par un côté et les blanches restent reliées.',
      'ظلّل بعض الخانات. الرقم يعدّ الخانات البيضاء المرئية منه في أربعة اتجاهات حتى خانة سوداء أو الحافة، وهو منها. لا تتجاور السوداوات، وتبقى البيضاوات متصلة.',
      'چند خانه را سیاه کن. عدد شمار خانه‌های سفید دیده‌شده از آن در چهار جهت تا خانه سیاه یا لبه است (خودش هم). سیاه‌ها پهلو به پهلو نیستند و سفیدها پیوسته‌اند.',
      'השחירו חלק מהמשבצות. מספר סופר את הלבנות הנראות ממנו בארבעה כיוונים עד שחורה או שוליים, כולל עצמו. שחורות לא נוגעות בצלע, והלבנות מחוברות.',
      'کچھ خانے سیاہ کریں۔ نمبر اس سے چار سمتوں میں سیاہ خانے یا کنارے تک دکھنے والے سفید خانے گنتا ہے، خود سمیت۔ سیاہ ساتھ نہیں لگتے، سفید جڑے رہتے ہیں۔',
      'Закрасьте часть клеток. Число — сколько белых клеток видно из него в четыре стороны до чёрной или края, включая его самого. Чёрные не соприкасаются сторонами, белые связаны.',
      'Зафарбуйте частину клітинок. Число — скільки білих клітинок видно з нього в чотири боки до чорної чи краю, включно з ним. Чорні не торкаються сторонами, білі зв\'язані.',
      'Zaczernij część pól. Liczba to białe pola widoczne z niej w czterech kierunkach do czarnego lub krawędzi, wliczając ją. Czarne nie stykają się bokami, białe są połączone.',
      'Začerni některá pole. Číslo počítá bílá pole viditelná z něj čtyřmi směry k černému nebo okraji, včetně sebe. Černá se nedotýkají stranou, bílá jsou spojená.',
      'Înnegrește unele celule. Numărul numără celulele albe vizibile din el în patru direcții până la una neagră sau margine, inclusiv el. Negrele nu se ating lateral, albele rămân unite.',
      'Feketíts be néhány mezőt. A szám a belőle négy irányban feketéig vagy szélig látható fehér mezőket számolja, önmagát is. Feketék oldalt nem érintkeznek, a fehérek összefüggők.',
      'Μαύρισε κάποια κελιά. Ο αριθμός μετρά τα λευκά που φαίνονται από αυτόν σε τέσσερις κατευθύνσεις ως μαύρο ή άκρη, μαζί με τον ίδιο. Τα μαύρα δεν ακουμπούν πλάι, τα λευκά ενωμένα.',
      'Annerisci alcune caselle. Un numero conta le bianche visibili nelle quattro direzioni fino a una nera o al bordo, compreso se stesso. Le nere non si toccano di lato, le bianche restano unite.',
      'Sombreie algumas casas. Um número conta as brancas visíveis em quatro direções até uma preta ou a borda, incluindo ele. As pretas não se tocam de lado e as brancas ficam ligadas.',
      'Kleur enkele vakjes zwart. Een getal telt de witte vakjes die het in vier richtingen ziet tot zwart of de rand, zichzelf inbegrepen. Zwarte raken elkaar niet zijdelings, witte blijven verbonden.',
      'Svärta några rutor. Ett tal räknar vita rutor det ser åt fyra håll till en svart eller kanten, sig själv inräknat. Svarta rör inte varandra på sidan, vita hänger ihop.',
      'Sværtn nogle felter. Et tal tæller de hvide felter, det ser i fire retninger til et sort eller kanten, sig selv medregnet. Sorte rører ikke hinanden på siden, hvide hænger sammen.',
      'Svert noen ruter. Et tall teller hvite ruter det ser i fire retninger til en svart eller kanten, seg selv inkludert. Svarte berører ikke hverandre sideveis, hvite henger sammen.',
      'Varjosta ruutuja. Luku laskee siitä neljään suuntaan mustaan tai reunaan asti näkyvät valkoiset, itsensä mukaan lukien. Mustat eivät kosketa sivuittain, valkoiset pysyvät yhtenäisinä.',
      'いくつかのマスを黒く塗ります。数字は、そこから上下左右に黒マスか端まで見える白マスの数（自分を含む）。黒マスは辺で接さず、白マスはひとつながり。',
      '몇 칸을 검게 칠하세요. 숫자는 그 칸에서 네 방향으로 검은 칸이나 끝까지 보이는 흰 칸 수(자신 포함)입니다. 검은 칸은 변으로 맞닿지 않고 흰 칸은 이어져 있습니다.',
      '涂黑部分格子。数字表示从该格向四个方向看到黑格或边缘为止的白格数（含自身）。黑格不能边相邻，白格保持连通。',
      'कुछ ख़ाने काले करें। अंक उस ख़ाने से चारों दिशाओं में काले या किनारे तक दिखते सफ़ेद ख़ाने गिनता है, स्वयं सहित। काले बगल में नहीं सटते, सफ़ेद जुड़े रहते हैं।',
      'কিছু ঘর কালো করুন। সংখ্যা সেখান থেকে চার দিকে কালো বা কিনারা পর্যন্ত দেখা সাদা ঘর গোনে, নিজেসহ। কালো পাশাপাশি ছোঁয় না, সাদা যুক্ত থাকে।',
      'Arsir beberapa sel. Angka menghitung sel putih yang terlihat ke empat arah sampai sel hitam atau tepi, termasuk dirinya. Hitam tak bersisian, putih tetap tersambung.',
      'Hitamkan beberapa petak. Nombor mengira petak putih yang nampak ke empat arah hingga hitam atau tepi, termasuk dirinya. Hitam tidak bersisian, putih kekal bersambung.',
      'ระบายดำบางช่อง ตัวเลขนับช่องขาวที่มองเห็นจากช่องนั้นสี่ทิศจนถึงช่องดำหรือขอบ รวมตัวเอง ช่องดำห้ามติดกันด้านข้าง ช่องขาวต้องเชื่อมกัน',
      'Tô đen một số ô. Số đếm các ô trắng nhìn thấy từ nó theo bốn hướng tới ô đen hoặc mép, kể cả chính nó. Ô đen không kề cạnh nhau, ô trắng liền một khối.',
      'Itiman ang ilang kahon. Binibilang ng numero ang puting tanaw nito sa apat na direksyon hanggang itim o gilid, kasama ang sarili. Hindi magkatabi ang itim at magkakadugtong ang puti.',
