      'Μαύρισε κάποια κελιά. Ο αριθμός μετρά τα λευκά που φαίνονται σε τέσσερις κατευθύνσεις ως μαύρο ή άκρη· το ίδιο το κελί δεν μετρά. Τα μαύρα δεν ακουμπούν πλάι, τα λευκά ενωμένα.',
      'Annerisci alcune caselle. Un numero conta le bianche visibili nelle quattro direzioni fino a una nera o al bordo; la casella del numero non conta. Le nere non si toccano di lato, le bianche restano unite.',
      'Sombreie algumas casas. Um número conta as brancas visíveis em quatro direções até uma preta ou a borda; a casa do número não conta. As pretas não se tocam de lado e as brancas ficam ligadas.',
      'Kleur enkele vakjes zwart. Een getal telt de witte vakjes die het in vier richtingen ziet tot zwart of de rand; het getalvakje zelf telt niet. Zwarte raken elkaar niet zijdelings, witte blijven verbonden.',
      'Svärta några rutor. Ett tal räknar vita rutor det ser åt fyra håll till svart eller kanten; talrutan själv räknas inte. Svarta rör inte varandra på sidan, vita hänger ihop.',
      'Sværtn nogle felter. Et tal tæller de hvide felter, det ser i fire retninger til sort eller kanten; talfeltet selv tæller ikke. Sorte rører ikke hinanden på siden, hvide hænger sammen.',
