      'Bazı hücreleri karala. Sayı, o hücreden dört yöne bakınca kara hücreye ya da kenara kadar görülen beyaz hücre sayısıdır; sayılı hücrenin kendisi sayılmaz. Karalar yan yana değmez, beyazlar tek parça kalır.',
      'Shade some cells. A number counts the white cells visible from it in four directions up to a black cell or the edge; the numbered cell itself does not count. Black cells never touch side by side and the white cells stay connected.',
      'Schwärze einige Felder. Eine Zahl zählt die weißen Felder, die sie in vier Richtungen bis Schwarz oder Rand sieht; das Zahlenfeld selbst zählt nicht. Schwarze berühren sich nicht seitlich, Weiße bleiben verbunden.',
      'Sombrea algunas casillas. Un número cuenta las blancas visibles en cuatro direcciones hasta una negra o el borde; la casilla del número no cuenta. Las negras no se tocan de lado y las blancas quedan unidas.',
      'Noircissez des cases. Un nombre compte les blanches visibles dans quatre directions jusqu\'à une noire ou au bord ; sa propre case ne compte pas. Les noires ne se touchent pas par un côté et les blanches restent reliées.',
      'ظلّل بعض الخانات. الرقم يعدّ الخانات البيضاء المرئية منه في أربعة اتجاهات حتى خانة سوداء أو الحافة؛ خانة الرقم نفسها لا تُحسب. لا تتجاور السوداوات، وتبقى البيضاوات متصلة.',
      'چند خانه را سیاه کن. عدد شمار خانه‌های سفید دیده‌شده از آن در چهار جهت تا سیاه یا لبه است؛ خانه خود عدد حساب نمی‌شود. سیاه‌ها پهلو به پهلو نیستند و سفیدها پیوسته‌اند.',
      'השחירו חלק מהמשבצות. מספר סופר את הלבנות הנראות ממנו בארבעה כיוונים עד שחורה או שוליים; משבצת המספר עצמה לא נספרת. שחורות לא נוגעות בצלע, והלבנות מחוברות.',
      'کچھ خانے سیاہ کریں۔ نمبر چار سمتوں میں سیاہ یا کنارے تک دکھنے والے سفید خانے گنتا ہے؛ نمبر والا خانہ خود شامل نہیں۔ سیاہ ساتھ نہیں لگتے، سفید جڑے رہتے ہیں۔',
      'Закрасьте часть клеток. Число — сколько белых клеток видно из него в четыре стороны до чёрной или края; сама клетка с числом не считается. Чёрные не соприкасаются сторонами, белые связаны.',
      'Зафарбуйте частину клітинок. Число — скільки білих клітинок видно з нього в чотири боки до чорної чи краю; сама клітинка з числом не рахується. Чорні не торкаються сторонами, білі зв\'язані.',
      'Zaczernij część pól. Liczba to białe pola widoczne z niej w czterech kierunkach do czarnego lub krawędzi; samo pole z liczbą się nie liczy. Czarne nie stykają się bokami, białe są połączone.',
      'Začerni některá pole. Číslo počítá bílá pole viditelná čtyřmi směry k černému nebo okraji; pole s číslem se nepočítá. Černá se nedotýkají stranou, bílá jsou spojená.',
      'Înnegrește unele celule. Numărul numără celulele albe vizibile în patru direcții până la una neagră sau margine; celula numărului nu se numără. Negrele nu se ating lateral, albele rămân unite.',
      'Feketíts be néhány mezőt. A szám a négy irányban feketéig vagy szélig látható fehér mezőket számolja; a számos mező nem számít. Feketék oldalt nem érintkeznek, a fehérek összefüggők.',
      'Μαύρισε κάποια κελιά. Ο αριθμός μετρά τα λευκά που φαίνονται σε τέσσερις κατευθύνσεις ως μαύρο ή άκρη· το ίδιο το κελί δεν μετρά. Τα μαύρα δεν ακουμπούν πλάι, τα λευκά ενωμένα.',
      'Annerisci alcune caselle. Un numero conta le bianche visibili nelle quattro direzioni fino a una nera o al bordo; la casella del numero non conta. Le nere non si toccano di lato, le bianche restano unite.',
      'Sombreie algumas casas. Um número conta as brancas visíveis em quatro direções até uma preta ou a borda; a casa do número não conta. As pretas não se tocam de lado e as brancas ficam ligadas.',
      'Kleur enkele vakjes zwart. Een getal telt de witte vakjes die het in vier richtingen ziet tot zwart of de rand; het getalvakje zelf telt niet. Zwarte raken elkaar niet zijdelings, witte blijven verbonden.',
      'Svärta några rutor. Ett tal räknar vita rutor det ser åt fyra håll till svart eller kanten; talrutan själv räknas inte. Svarta rör inte varandra på sidan, vita hänger ihop.',
      'Sværtn nogle felter. Et tal tæller de hvide felter, det ser i fire retninger til sort eller kanten; talfeltet selv tæller ikke. Sorte rører ikke hinanden på siden, hvide hænger sammen.',
