      'いくつかのマスを黒く塗ります。数字は上下左右に黒マスか端まで見える白マスの数で、数字のマス自身は数えません。黒マスは辺で接さず、白マスはひとつながり。',
      '몇 칸을 검게 칠하세요. 숫자는 네 방향으로 검은 칸이나 끝까지 보이는 흰 칸 수이며 숫자 칸 자신은 세지 않습니다. 검은 칸은 맞닿지 않고 흰 칸은 이어져 있습니다.',
      '涂黑部分格子。数字表示向四个方向看到黑格或边缘为止的白格数，不含数字格本身。黑格不能边相邻，白格保持连通。',
      'कुछ ख़ाने काले करें। अंक चारों दिशाओं में काले या किनारे तक दिखते सफ़ेद ख़ाने गिनता है; अंक वाला ख़ाना ख़ुद नहीं गिना जाता। काले बगल में नहीं सटते, सफ़ेद जुड़े रहते हैं।',
      'কিছু ঘর কালো করুন। সংখ্যা চার দিকে কালো বা কিনারা পর্যন্ত দেখা সাদা ঘর গোনে; সংখ্যার ঘরটি নিজে গোনা হয় না। কালো পাশাপাশি ছোঁয় না, সাদা যুক্ত থাকে।',
      'Arsir beberapa sel. Angka menghitung sel putih yang terlihat ke empat arah sampai hitam atau tepi; sel angka sendiri tidak dihitung. Hitam tak bersisian, putih tetap tersambung.',
