      'ระบายดำบางช่อง ตัวเลขนับช่องขาวที่มองเห็นสี่ทิศจนถึงช่องดำหรือขอบ ไม่นับช่องตัวเลขเอง ช่องดำห้ามติดกันด้านข้าง ช่องขาวต้องเชื่อมกัน',
