  tutorial: const [
    TutorialStep(Icons.extension, [
      'Beyaz hücrelere ampul koy; ampul satır ve sütun boyunca duvara kadar ışık saçar. Bütün beyaz hücreler aydınlansın, iki ampul birbirini görmesin. Duvardaki sayı, ona bitişik ampul sayısıdır.',
      'Put bulbs in white cells; each lights its row and column up to a wall. Every white cell must be lit and no two bulbs may see each other. A number on a wall tells how many bulbs touch it.',
      'Setze Lampen in weiße Felder; sie leuchten Zeile und Spalte bis zur Wand aus. Alle weißen Felder hell, keine zwei Lampen sehen sich. Eine Zahl an der Wand nennt angrenzende Lampen.',
      'Pon bombillas en casillas blancas; iluminan fila y columna hasta un muro. Todo debe quedar iluminado y ninguna bombilla ve a otra. El número de un muro indica bombillas contiguas.',
      'Placez des ampoules dans les cases blanches ; elles éclairent ligne et colonne jusqu\'au mur. Tout doit être éclairé, sans que deux ampoules se voient. Le chiffre d\'un mur donne les ampoules voisines.',
      'ضع مصابيح في الخانات البيضاء؛ تضيء الصف والعمود حتى الجدار. يجب إضاءة كل خانة ولا يرى مصباح آخر. الرقم على الجدار عدد المصابيح الملاصقة.',
      'در خانه‌های سفید لامپ بگذار؛ سطر و ستون را تا دیوار روشن می‌کند. همه خانه‌ها روشن شوند و دو لامپ یکدیگر را نبینند. عدد دیوار تعداد لامپ‌های چسبیده است.',
      'הציבו נורות במשבצות לבנות; הן מאירות שורה ועמודה עד קיר. כל לבן מואר ושתי נורות לא רואות זו את זו. מספר על קיר הוא מספר הנורות הצמודות.',
      'سفید خانوں میں بلب لگائیں؛ وہ قطار اور کالم کو دیوار تک روشن کرتے ہیں۔ ہر سفید روشن ہو اور دو بلب ایک دوسرے کو نہ دیکھیں۔ دیوار کا نمبر ساتھ لگے بلب بتاتا ہے۔',
      'Ставьте лампы в белые клетки; они светят по строке и столбцу до стены. Всё должно быть освещено, лампы не видят друг друга. Число на стене — число соседних ламп.',
      'Ставте лампи в білі клітинки; вони світять рядком і стовпцем до стіни. Усе має бути освітлене, лампи не бачать одна одну. Число на стіні — кількість сусідніх ламп.',
      'Stawiaj żarówki w białych polach; świecą wzdłuż wiersza i kolumny do ściany. Wszystko oświetlone, żarówki się nie widzą. Liczba na ścianie to sąsiednie żarówki.',
      'Dávej žárovky do bílých polí; svítí řádkem a sloupcem ke zdi. Vše osvětleno, žárovky se nevidí. Číslo na zdi je počet sousedních žárovek.',
      'Pune becuri în celule albe; luminează rândul și coloana până la zid. Totul luminat, becurile nu se văd. Numărul pe zid arată becurile vecine.',
      'Tegyél izzót fehér mezőkbe; soron és oszlopon falig világít. Minden mező világos legyen, két izzó ne lássa egymást. A falon lévő szám a szomszédos izzók száma.',
      'Βάλε λάμπες σε λευκά κελιά· φωτίζουν γραμμή και στήλη ως τον τοίχο. Όλα φωτισμένα, καμία λάμπα δεν βλέπει άλλη. Ο αριθμός στον τοίχο δείχνει τις γειτονικές λάμπες.',
      'Metti lampadine nelle caselle bianche; illuminano riga e colonna fino a un muro. Tutto illuminato, nessuna lampadina ne vede un\'altra. Il numero sul muro indica le lampadine adiacenti.',
      'Ponha lâmpadas nas casas brancas; iluminam linha e coluna até uma parede. Tudo iluminado, sem lâmpadas a verem-se. O número na parede indica lâmpadas vizinhas.',
      'Plaats lampen in witte vakjes; ze verlichten rij en kolom tot een muur. Alles verlicht, geen twee lampen zien elkaar. Een getal op een muur noemt de aangrenzende lampen.',
      'Sätt lampor i vita rutor; de lyser längs rad och kolumn till en vägg. Allt upplyst, inga lampor ser varandra. Talet på en vägg anger angränsande lampor.',
      'Sæt pærer i hvide felter; de lyser række og søjle op til en mur. Alt oplyst, ingen pærer ser hinanden. Tallet på en mur angiver nabopærer.',
      'Sett pærer i hvite ruter; de lyser rad og kolonne til en vegg. Alt opplyst, ingen pærer ser hverandre. Tallet på en vegg angir nabopærer.',
      'Aseta lamppuja valkoisiin ruutuihin; ne valaisevat rivin ja sarakkeen seinään asti. Kaikki valaistu, lamput eivät näe toisiaan. Seinän luku kertoo viereiset lamput.',
      '白マスに電球を置くと、縦横に壁まで照らします。白マスをすべて照らし、電球同士は見えてはいけません。壁の数字は隣接する電球の数。',
      '흰 칸에 전구를 놓으면 가로세로로 벽까지 비춥니다. 모든 흰 칸을 밝히고 전구끼리 마주 보면 안 됩니다. 벽의 숫자는 맞닿은 전구 수.',
