      'מלאו כל תא ב-○ או ●. אין שלושה זהים ברצף, בכל שורה ועמודה כמות שווה של ○ ו-●, ואין שתי שורות (או עמודות) זהות.',
      'ہر خانے میں ○ یا ● رکھیں۔ تین ایک جیسے ساتھ نہیں، ہر قطار و کالم میں ○ اور ● برابر، اور کوئی دو قطاریں (یا کالم) یکساں نہیں۔',
      'Заполните клетки ○ или ●. Не три одинаковых подряд, в каждой строке и столбце поровну ○ и ●, и нет двух одинаковых строк (или столбцов).',
      'Заповніть клітинки ○ або ●. Не три однакових поспіль, у кожному рядку й стовпці порівну ○ і ●, і немає двох однакових рядків (чи стовпців).',
      'Wypełnij pola ○ lub ●. Nie trzy takie same z rzędu, w każdym wierszu i kolumnie tyle samo ○ co ●, i żadne dwa wiersze (kolumny) nie są identyczne.',
      'Vyplň pole ○ nebo ●. Nikdy tři stejné za sebou, v každém řádku a sloupci stejně ○ jako ●, žádné dva řádky (sloupce) nejsou stejné.',
      'Completează fiecare căsuță cu ○ sau ●. Niciodată trei la rând, fiecare rând și coloană au tot atâtea ○ cât ●, iar două rânduri (sau coloane) nu sunt identice.',
      'Tölts minden mezőbe ○ vagy ● jelet. Nincs három egyforma egymás mellett, minden sorban és oszlopban ugyanannyi ○ és ●, és nincs két egyforma sor (oszlop).',
      'Γέμισε κάθε κελί με ○ ή ●. Όχι τρία ίδια στη σειρά, κάθε γραμμή και στήλη έχει ίσα ○ και ●, και καμία γραμμή (ή στήλη) δεν είναι ίδια με άλλη.',
      'Riempi ogni casella con ○ o ●. Mai tre uguali di fila, ogni riga e colonna ha tanti ○ quanti ●, e due righe (o colonne) non sono mai identiche.',
      'Preencha cada casa com ○ ou ●. Nunca três iguais seguidos, cada linha e coluna tem tantos ○ quanto ●, e não há duas linhas (ou colunas) iguais.',
      'Vul elk vakje met ○ of ●. Nooit drie dezelfde op een rij, elke rij en kolom heeft evenveel ○ als ●, en geen twee rijen (of kolommen) zijn gelijk.',
      'Fyll varje ruta med ○ eller ●. Aldrig tre lika i rad, varje rad och kolumn har lika många ○ som ●, och inga två rader (kolumner) är lika.',
      'Udfyld hvert felt med ○ eller ●. Aldrig tre ens i træk, hver række og kolonne har lige mange ○ og ●, og ingen to rækker (kolonner) er ens.',
      'Fyll hver rute med ○ eller ●. Aldri tre like på rad, hver rad og kolonne har like mange ○ som ●, og ingen to rader (kolonner) er like.',
      'Täytä ruudut ○:lla tai ●:llä. Ei kolmea samaa peräkkäin, jokaisessa rivissä ja sarakkeessa yhtä monta ○ ja ●, eikä kahta samanlaista riviä (saraketta).',
      '各マスに○か●。同じものが3つ並ばず、各行・列の○と●は同数で、同じ並びの行（列）は2つありません。',
      '각 칸에 ○나 ●를 넣으세요. 같은 것이 셋 연속되지 않고, 각 행·열의 ○와 ● 수가 같으며, 같은 행(열)이 둘 있을 수 없습니다.',
      '每格填○或●。不能有三个相同相连，每行每列○与●数量相等，且任意两行（或两列）不相同。',
