      'প্রতিটি ঘরে ○ বা ●। পরপর তিনটি একই নয়, প্রতিটি সারি-কলামে ○ ও ● সমান, আর দুটি সারি (কলাম) এক নয়।',
      'Isi tiap sel dengan ○ atau ●. Tak ada tiga sama berurutan, tiap baris dan kolom punya ○ dan ● sama banyak, dan tak ada dua baris (kolom) identik.',
      'Isi setiap petak dengan ○ atau ●. Tiada tiga sama berturut-turut, setiap baris dan lajur ada ○ dan ● sama banyak, dan tiada dua baris (lajur) serupa.',
      'ใส่ ○ หรือ ● ทุกช่อง ห้ามเหมือนกันสามตัวติด ทุกแถวและคอลัมน์มี ○ และ ● เท่ากัน และไม่มีสองแถว (คอลัมน์) ที่เหมือนกัน',
      'Điền ○ hoặc ● vào mỗi ô. Không ba ô giống nhau liền nhau, mỗi hàng và cột có số ○ bằng ●, và không hai hàng (cột) nào giống nhau.',
      'Punan ang bawat cell ng ○ o ●. Walang tatlong magkapareho nang sunod, pantay ang ○ at ● sa bawat hanay at kolum, at walang dalawang magkaparehong hanay (kolum).',
