      'Placez les navires listés en bas. Ils sont droits et ne se touchent jamais, même en diagonale. Les nombres des rangées et colonnes comptent les cases de navire. Certaines cases sont révélées.',
      'ضع السفن المدرجة في الأسفل على الشبكة. تكون مستقيمة ولا تتلامس ولو قطريًا. أرقام الصفوف والأعمدة تعدّ خانات السفن. بعض الخانات مكشوفة.',
      'کشتی‌های فهرست پایین را بچین. صاف‌اند و حتی قطری به هم نمی‌خورند. اعداد کنار سطر و ستون تعداد خانه‌های کشتی است. چند خانه از آغاز باز است.',
      'מקמו את הספינות שברשימה למטה. הן ישרות ולא נוגעות זו בזו, גם לא באלכסון. המספרים ליד שורות ועמודות סופרים משבצות ספינה. חלק מהמשבצות גלויות.',
      'نیچے فہرست کے جہاز گرڈ میں رکھیں۔ جہاز سیدھے ہوتے ہیں اور ترچھے بھی نہیں چھوتے۔ قطار و کالم کے نمبر جہاز کے خانے گنتے ہیں۔ کچھ خانے پہلے سے کھلے ہیں۔',
      'Расставьте корабли из списка внизу. Они прямые и не касаются друг друга даже углами. Числа у строк и столбцов — клетки кораблей. Некоторые клетки открыты.',
      'Розставте кораблі зі списку внизу. Вони прямі й не торкаються навіть кутами. Числа біля рядків і стовпців — клітинки кораблів. Деякі клітинки відкриті.',
      'Ustaw statki z listy na dole. Są proste i nie stykają się nawet rogami. Liczby przy wierszach i kolumnach liczą pola statków. Część pól jest odkryta.',
      'Rozmísti lodě ze seznamu dole. Jsou rovné a nedotýkají se ani rohy. Čísla u řádků a sloupců počítají pole lodí. Některá pole jsou odkrytá.',
      'Așază navele din lista de jos. Sunt drepte și nu se ating nici pe diagonală. Numerele rândurilor și coloanelor numără celulele de navă. Unele celule sunt dezvăluite.',
      'Tedd le a lent felsorolt hajókat. Egyenesek, és átlósan sem érintkeznek. A sorok és oszlopok számai a hajómezőket számolják. Néhány mező fel van fedve.',
      'Βάλε τα πλοία της λίστας κάτω. Είναι ευθεία και δεν ακουμπούν ούτε διαγώνια. Οι αριθμοί γραμμών και στηλών μετρούν κελιά πλοίων. Κάποια κελιά είναι ανοιχτά.',
      'Piazza le navi elencate in basso. Sono dritte e non si toccano mai, nemmeno in diagonale. I numeri di righe e colonne contano le caselle nave. Alcune caselle sono già scoperte.',
      'Coloque os navios da lista em baixo. São retos e nunca se tocam, nem na diagonal. Os números de linhas e colunas contam casas de navio. Algumas casas começam reveladas.',
      'Plaats de schepen uit de lijst onderaan. Ze liggen recht en raken elkaar nooit, ook niet diagonaal. De getallen bij rijen en kolommen tellen scheepsvakjes. Sommige vakjes zijn al open.',
      'Placera skeppen i listan nedtill. De ligger rakt och rör aldrig varandra, inte ens diagonalt. Talen vid rader och kolumner räknar skeppsrutor. Några rutor är avslöjade.',
      'Placér skibene fra listen forneden. De ligger lige og rører aldrig hinanden, heller ikke diagonalt. Tallene ved rækker og søjler tæller skibsfelter. Nogle felter er afsløret.',
      'Plasser skipene fra listen nederst. De ligger rett og berører aldri hverandre, heller ikke diagonalt. Tallene ved rader og kolonner teller skipsruter. Noen ruter er avslørt.',
