      '下の一覧の船を盤に置きます。船はまっすぐで、斜めも含め互いに接しません。行・列の横の数字はその列の船マスの数。最初から開いているマスもあります。',
      '아래 목록의 배를 격자에 놓으세요. 배는 곧게 놓이며 대각선으로도 맞닿지 않습니다. 행·열 옆의 숫자는 그 줄의 배 칸 수. 일부 칸은 처음부터 열려 있습니다.',
