      'নিচের তালিকার জাহাজ গ্রিডে বসান। জাহাজ সোজা এবং কোণাকুণিও ছোঁয় না। সারি ও কলামের সংখ্যা জাহাজের ঘর গোনে। কিছু ঘর শুরু থেকেই খোলা।',
