      'วางเรือตามรายการด้านล่างลงตาราง เรือวางตรงและไม่แตะกันแม้แนวทแยง เลขข้างแถวและคอลัมน์คือจำนวนช่องเรือ บางช่องเปิดไว้แล้ว',
