      'כל אזור הוא מיכל שמתמלא מלמטה עד גובה מסוים: אם משבצת מלאה, כל משבצות המיכל באותו גובה או נמוך יותר מלאות. מספרים בשוליים סופרים מלאות בשורה או עמודה.',
      'ہر علاقہ ایک ٹینک ہے جو نیچے سے کسی سطح تک بھرتا ہے: اگر ایک خانہ بھرا ہو تو اسی ٹینک کے اتنی یا کم اونچائی کے سب خانے بھرے ہوں۔ کنارے کے نمبر قطار یا کالم کے بھرے خانے گنتے ہیں۔',
      'Каждая область — бак, налитый снизу до какого-то уровня: если клетка полна, все клетки этого бака на той же высоте и ниже тоже. Числа по краю — полные клетки в строке или столбце.',
      'Кожна область — бак, налитий знизу до певного рівня: якщо клітинка повна, усі клітинки цього бака на тій самій висоті й нижче теж. Числа на краю — повні клітинки в рядку чи стовпці.',
      'Każdy obszar to zbiornik napełniony od dna do pewnego poziomu: jeśli pole jest pełne, pełne są też wszystkie pola tego zbiornika na tej wysokości i niżej. Liczby z boku liczą pełne pola.',
      'Každá oblast je nádrž naplněná ode dna do určité výšky: je-li pole plné, plná jsou i všechna pole té nádrže ve stejné výšce a níž. Čísla na okraji počítají plná pole.',
      'Fiecare zonă e un bazin umplut de jos până la un nivel: dacă o celulă e plină, toate celulele bazinului la aceeași înălțime sau mai jos sunt pline. Numerele de pe margine numără celulele pline.',
      'Minden terület egy tartály, alulról valamilyen szintig töltve: ha egy mező teli, a tartály minden azonos magasságú vagy lejjebb lévő mezője is. A szélső számok a teli mezőket számolják.',
      'Κάθε περιοχή είναι δεξαμενή γεμάτη από κάτω ως ένα ύψος: αν ένα κελί είναι γεμάτο, γεμάτα είναι κι όλα του ίδιου ύψους ή χαμηλότερα. Οι αριθμοί άκρης μετρούν γεμάτα κελιά.',
      'Ogni zona è una vasca riempita dal fondo fino a un livello: se una casella è piena, lo sono tutte quelle della vasca alla stessa altezza o più in basso. I numeri sul bordo contano le piene.',
      'Cada região é um tanque cheio do fundo até um nível: se uma casa está cheia, todas as do tanque à mesma altura ou abaixo também estão. Os números da borda contam casas cheias.',
      'Elk gebied is een bak die van onder tot een niveau vol is: is een vakje vol, dan zijn alle vakjes van die bak op dezelfde hoogte of lager ook vol. Randgetallen tellen volle vakjes.',
      'Varje område är en tank fylld nerifrån till en nivå: är en ruta full är alla rutor i tanken på samma höjd eller lägre också fulla. Kanttalen räknar fulla rutor.',
      'Hvert område er en tank fyldt nedefra til et niveau: er et felt fuldt, er alle felter i tanken i samme højde eller lavere også fulde. Kanttallene tæller fulde felter.',
      'Hvert område er en tank fylt nedenfra til et nivå: er en rute full, er alle ruter i tanken i samme høyde eller lavere også fulle. Kanttallene teller fulle ruter.',
      'Jokainen alue on allas, joka täyttyy pohjalta tiettyyn tasoon: jos ruutu on täynnä, kaikki saman altaan ruudut samalla korkeudella tai alempana ovat täynnä. Reunaluvut laskevat täydet ruudut.',
      '各エリアは水そうで、底からある高さまで水が入ります。あるマスに水があれば、同じ水そうの同じ高さ以下のマスにもすべて水があります。端の数字は行・列の水のマス数。',
      '각 영역은 바닥부터 어느 높이까지 물이 차는 수조입니다. 한 칸에 물이 있으면 같은 수조의 같은 높이 이하 칸은 모두 찹니다. 가장자리 숫자는 행·열의 물 찬 칸 수.',
      '每个区域是一个水箱，从底部灌到某一水位：若某格有水，同一水箱中同高或更低的格子也都有水。边上数字表示该行或列有水的格数。',
      'हर क्षेत्र एक टैंक है जो नीचे से किसी स्तर तक भरता है: कोई ख़ाना भरा हो तो उसी टैंक के उतनी या कम ऊँचाई के सब ख़ाने भरे हों। किनारे के अंक भरे ख़ाने गिनते हैं।',
      'প্রতিটি অঞ্চল একটি ট্যাংক, নিচ থেকে কোনো স্তর পর্যন্ত ভরে: কোনো ঘর ভরা হলে সেই ট্যাংকের সমান বা নিচু সব ঘরও ভরা। কিনারার সংখ্যা ভরা ঘর গোনে।',
      'Tiap wilayah adalah tangki yang terisi dari dasar sampai level tertentu: jika satu sel penuh, semua sel tangki itu pada ketinggian sama atau lebih rendah juga penuh. Angka tepi menghitung sel penuh.',
      'Setiap kawasan ialah tangki yang diisi dari dasar hingga paras tertentu: jika satu petak penuh, semua petak tangki itu pada ketinggian sama atau lebih rendah juga penuh. Nombor tepi mengira petak penuh.',
      'แต่ละพื้นที่คือตู้ที่เติมน้ำจากก้นถึงระดับหนึ่ง ถ้าช่องหนึ่งมีน้ำ ทุกช่องในตู้เดียวกันที่สูงเท่ากันหรือต่ำกว่าต้องมีน้ำ เลขที่ขอบนับช่องที่มีน้ำ',
      'Mỗi vùng là một bể đầy nước từ đáy lên tới một mức: nếu một ô đầy, mọi ô cùng bể ở cùng độ cao hoặc thấp hơn cũng đầy. Số ở mép đếm ô đầy trong hàng hoặc cột.',
