      'Her bölgede tam iki hücreyi karala. Her kara hücrenin tam bir kara komşusu olsun; yani karalar ikişerli domino oluşturur. Bir domino iki bölgeye yayılabilir.',
      'Shade exactly two cells in every region. Every black cell has exactly one black neighbor, so the black cells form domino pairs. A domino may span two regions.',
      'Schwärze in jedem Gebiet genau zwei Felder. Jedes schwarze Feld hat genau einen schwarzen Nachbarn, die Schwarzen bilden also Dominos. Ein Domino darf zwei Gebiete überspannen.',
