      'Закрасьте ровно две клетки в каждой области. У каждой чёрной ровно одна чёрная соседка, так что они образуют пары-домино. Домино может занимать две области.',
      'Зафарбуйте рівно дві клітинки в кожній області. Кожна чорна має рівно одну чорну сусідку, тож вони утворюють пари-доміно. Доміно може займати дві області.',
