      'V každé oblasti začerni přesně dvě pole. Každé černé má přesně jednoho černého souseda, takže tvoří domina. Domino může zasahovat do dvou oblastí.',
      'Înnegrește exact două celule în fiecare zonă. Fiecare neagră are exact o vecină neagră, deci formează domino. Un domino poate trece prin două zone.',
      'Minden területen pontosan két mezőt feketíts be. Minden feketének pontosan egy fekete szomszédja van, így dominókat alkotnak. Egy dominó két területre is eshet.',
      'Μαύρισε ακριβώς δύο κελιά σε κάθε περιοχή. Κάθε μαύρο έχει ακριβώς έναν μαύρο γείτονα, άρα σχηματίζουν ντόμινο. Ένα ντόμινο μπορεί να εκτείνεται σε δύο περιοχές.',
      'Annerisci esattamente due caselle per zona. Ogni nera ha esattamente una vicina nera, quindi formano tessere domino. Una tessera può stare su due zone.',
