      '各エリアでちょうど2マスを黒く塗ります。黒マスはどれもちょうど1つの黒マスと隣り合い、ドミノの形になります。ドミノは2つのエリアにまたがってもかまいません。',
      '각 영역에서 정확히 두 칸을 칠하세요. 모든 검은 칸은 검은 이웃이 정확히 하나라서 도미노 쌍이 됩니다. 도미노는 두 영역에 걸칠 수 있습니다.',
