      'हर क्षेत्र में ठीक दो ख़ाने काले करें। हर काले का ठीक एक काला पड़ोसी हो, यानी काले डोमिनो जोड़े बनाते हैं। एक डोमिनो दो क्षेत्रों में फैल सकता है।',
      'প্রতিটি অঞ্চলে ঠিক দুটি ঘর কালো করুন। প্রতিটি কালোর ঠিক একটি কালো প্রতিবেশী, তাই ডমিনো জোড়া হয়। একটি ডমিনো দুটি অঞ্চলে ছড়াতে পারে।',
