      'ระบายดำสองช่องพอดีในทุกพื้นที่ ช่องดำทุกช่องมีเพื่อนบ้านดำหนึ่งช่องพอดี จึงเป็นคู่โดมิโน โดมิโนหนึ่งตัวคร่อมสองพื้นที่ได้',
