      'Οι αριθμοί ένδειξης είναι τα μήκη των μαύρων σειρών στα 8 γύρω κελιά (με οποιαδήποτε σειρά). Όλα τα μαύρα ενωμένα, χωρίς 2x2· τα κελιά ενδείξεων λευκά.',
