      'Talen i en ledtrådsruta är längderna på svarta följder i de 8 rutorna runt om (valfri ordning). Alla svarta hänger ihop, inget 2x2-block; ledtrådsrutor förblir vita.',
      'Tallene i et ledetrådsfelt er længderne på sorte serier i de 8 felter rundt om (vilkårlig rækkefølge). Alle sorte hænger sammen, ingen 2x2-blok; ledetrådsfelter er hvide.',
