      'Rajzolj egy zárt hurkot a mezőközepeken át minden gyöngyön keresztül. Fehéren egyenesen megy, és közvetlenül előtte vagy utána fordul. Feketén fordul, és mindkét irányba legalább egy mezőt egyenesen megy.',
      'Σχεδίασε έναν κλειστό βρόχο από τα κέντρα κελιών που περνά από όλα τα μαργαριτάρια. Στο λευκό ευθεία και στροφή ακριβώς πριν ή μετά. Στο μαύρο στροφή και τουλάχιστον ένα κελί ευθεία προς κάθε πλευρά.',
      'Traccia un anello chiuso tra i centri delle caselle che tocchi tutte le perle. Sulla bianca va dritto e gira subito prima o dopo. Sulla nera gira e prosegue dritto almeno una casella per lato.',
      'Trace um laço fechado pelos centros das casas que passe por todas as pérolas. Na branca segue reto e vira logo antes ou depois. Na preta vira e segue reto pelo menos uma casa para cada lado.',
