      'Rita en sluten slinga genom rutmitter som passerar alla pärlor. På vit rakt fram och sväng strax före eller efter. På svart sväng och minst en ruta rakt åt båda hållen.',
      'Tegn én lukket løkke gennem feltmidter, der passerer alle perler. På hvid lige igennem og drej lige før eller efter. På sort drej og mindst ét felt lige ud til begge sider.',
      'Tegn én lukket sløyfe gjennom rutemidter som passerer alle perler. På hvit rett frem og sving rett før eller etter. På svart sving og minst én rute rett frem til begge sider.',
      'Piirrä ruutujen keskipisteiden kautta yksi suljettu silmukka kaikkien helmien läpi. Valkoisella suoraan ja käännös heti ennen tai jälkeen. Mustalla käännös ja vähintään ruutu suoraan kumpaankin suuntaan.',
