      '칸 중심을 지나는 닫힌 고리 하나를 그려 모든 진주를 지나세요. 흰 진주는 곧게 지나고 바로 앞이나 뒤에서 꺾입니다. 검은 진주에서는 꺾고 양쪽으로 한 칸 이상 곧게 갑니다.',
      '画一条经过格子中心的闭合回路并穿过所有珍珠。白珠处直行，并在其前或后一格转弯。黑珠处转弯，且两侧至少各直行一格。',
      'ख़ानों के केंद्र से एक बंद घेरा बनाएँ जो हर मोती से गुज़रे। सफ़ेद पर सीधा और ठीक पहले या बाद मुड़े। काले पर मुड़े और दोनों ओर कम से कम एक ख़ाना सीधा।',
