      'Táhni z ostrova na ostrov nebo klepni do mezery: jeden most, dva, pak zrušit. Mosty jsou rovné a nekříží se; číslo je počet mostů a všechny ostrovy jsou spojené.',
      'Trage de la insulă la insulă sau atinge golul dintre ele: pod simplu, dublu, apoi eliminat. Podurile sunt drepte și nu se intersectează; numărul e numărul de poduri, toate insulele legate.',
