      'Arraste de ilha a ilha ou toque no espaço entre elas: ponte simples, dupla, depois remove. Pontes são retas e não se cruzam; o número é a quantidade de pontes e todas as ilhas ficam ligadas.',
      'Sleep van eiland naar eiland of tik de ruimte ertussen: enkele brug, dubbele, dan weg. Bruggen zijn recht en kruisen niet; het getal is het aantal bruggen en alle eilanden zijn verbonden.',
