      'एक द्वीप से दूसरे तक खींचें या बीच की जगह छुएँ: एक पुल, दो, फिर हटाएँ। पुल सीधे हैं और कटते नहीं; संख्या पुलों की गिनती है, सारे द्वीप जुड़े हों।',
