      'Nakresli / nebo \\ do každého pole (klepnutím přepni). Číslo v rohu udává, kolik čar se dotýká bodu. Čáry nikdy netvoří uzavřenou smyčku.',
      'Desenează / sau \\ în fiecare celulă (atinge pentru schimbare). Numărul dintr-un colț arată câte linii ating punctul. Liniile nu formează niciodată o buclă închisă.',
