  buildPlay: (ctx) => PuzzleView(ctx: ctx, rules: mantikHayaletlerMiniRules),
  tutorial: const [
    TutorialStep(Icons.extension, [
      'Boş hücrelere hayalet, vampir ya da zombi koy (toplamlar üstte yazar). Kenardaki sayı, o noktadan içeri bakınca aynalardan sekerek görülen yaratık sayısıdır. Zombi hep görünür; vampir yalnızca aynaya gelmeden, hayalet yalnızca aynada yansıdıktan sonra görünür.',
      'Place ghosts, vampires or zombies in empty cells (totals are shown above). An edge number counts the creatures seen looking in from there, bouncing off mirrors. Zombies are always seen; vampires only before the first mirror, ghosts only after it.',
      'Setze Geister, Vampire oder Zombies in leere Felder (Summen stehen oben). Eine Randzahl zählt die Wesen, die man von dort mit Spiegelungen sieht. Zombies sieht man immer, Vampire nur vor dem ersten Spiegel, Geister nur danach.',
      'Coloca fantasmas, vampiros o zombis en casillas vacías (los totales arriba). Un número del borde cuenta las criaturas vistas desde ahí rebotando en espejos. Los zombis siempre se ven; los vampiros solo antes del primer espejo, los fantasmas solo después.',
      'Placez fantômes, vampires ou zombies dans les cases vides (totaux en haut). Un nombre au bord compte les créatures vues depuis là, en rebondissant sur les miroirs. Zombies toujours visibles ; vampires seulement avant le premier miroir, fantômes seulement après.',
      'ضع أشباحًا أو مصاصي دماء أو زومبي في الخانات الفارغة (المجاميع في الأعلى). رقم الحافة يعدّ المخلوقات المرئية من هناك مع الانعكاس في المرايا. الزومبي يُرى دائمًا، ومصاص الدماء قبل أول مرآة فقط، والشبح بعدها فقط.',
      'در خانه‌های خالی شبح، خون‌آشام یا زامبی بگذار (مجموع‌ها بالا). عدد لبه شمار موجوداتی است که از آنجا با بازتاب آینه دیده می‌شوند. زامبی همیشه، خون‌آشام فقط پیش از نخستین آینه و شبح فقط پس از آن دیده می‌شود.',
      'הציבו רוחות, ערפדים או זומבים במשבצות ריקות (הסכומים למעלה). מספר בשוליים סופר את היצורים הנראים משם עם החזרות במראות. זומבי תמיד נראה; ערפד רק לפני המראה הראשונה, רוח רק אחריה.',
      'خالی خانوں میں بھوت، ویمپائر یا زومبی رکھیں (کل اوپر)۔ کنارے کا نمبر وہاں سے آئینوں میں منعکس ہو کر دکھنے والی مخلوق گنتا ہے۔ زومبی ہمیشہ، ویمپائر پہلے آئینے سے پہلے، بھوت صرف اس کے بعد دکھتا ہے۔',
      'Ставьте призраков, вампиров или зомби в пустые клетки (итоги сверху). Число на краю — сколько существ видно оттуда с отражениями в зеркалах. Зомби видны всегда; вампиры — только до первого зеркала, призраки — только после.',
      'Ставте привидів, вампірів або зомбі в порожні клітинки (підсумки вгорі). Число на краю — скільки істот видно звідти з відбиттями в дзеркалах. Зомбі видно завжди; вампірів — лише до першого дзеркала, привидів — лише після.',
      'Umieść duchy, wampiry lub zombie w pustych polach (sumy u góry). Liczba z boku liczy stwory widoczne stamtąd z odbiciami w lustrach. Zombie widać zawsze; wampiry tylko przed pierwszym lustrem, duchy tylko po nim.',
      'Rozmísti duchy, upíry nebo zombie do prázdných polí (součty nahoře). Číslo na okraji počítá bytosti viditelné odtud s odrazy v zrcadlech. Zombie jsou vidět vždy; upíři jen před prvním zrcadlem, duchové jen po něm.',
      'Pune fantome, vampiri sau zombi în celulele goale (totalurile sus). Un număr de pe margine numără creaturile văzute de acolo, prin reflexii în oglinzi. Zombii se văd mereu; vampirii doar înainte de prima oglindă, fantomele doar după.',
      'Tegyél szellemet, vámpírt vagy zombit az üres mezőkbe (összegek fent). A szélső szám az onnan tükröződve látott lényeket számolja. Zombi mindig látszik; vámpír csak az első tükör előtt, szellem csak utána.',
      'Βάλε φαντάσματα, βρικόλακες ή ζόμπι σε κενά κελιά (σύνολα πάνω). Ο αριθμός στην άκρη μετρά πλάσματα ορατά από εκεί με ανακλάσεις. Ζόμπι φαίνονται πάντα· βρικόλακες μόνο πριν τον πρώτο καθρέφτη, φαντάσματα μόνο μετά.',
      'Metti fantasmi, vampiri o zombi nelle caselle vuote (totali in alto). Un numero sul bordo conta le creature viste da lì rimbalzando sugli specchi. Zombi sempre visibili; vampiri solo prima del primo specchio, fantasmi solo dopo.',
      'Ponha fantasmas, vampiros ou zombis nas casas vazias (totais em cima). Um número na borda conta as criaturas vistas dali, refletindo nos espelhos. Zombis veem-se sempre; vampiros só antes do primeiro espelho, fantasmas só depois.',
      'Zet spoken, vampiers of zombies in lege vakjes (totalen boven). Een randgetal telt de wezens die je van daaruit via spiegels ziet. Zombies zie je altijd; vampiers alleen vóór de eerste spiegel, spoken alleen erna.',
      'Placera spöken, vampyrer eller zombier i tomma rutor (summor ovanför). Ett kanttal räknar varelser som syns därifrån via speglar. Zombier syns alltid; vampyrer bara före första spegeln, spöken bara efter.',
      'Placér spøgelser, vampyrer eller zombier i tomme felter (summer foroven). Et kanttal tæller væsner set derfra via spejle. Zombier ses altid; vampyrer kun før første spejl, spøgelser kun efter.',
      'Plasser spøkelser, vampyrer eller zombier i tomme ruter (summer øverst). Et kanttall teller vesener sett derfra via speil. Zombier ses alltid; vampyrer bare før første speil, spøkelser bare etter.',
      'Aseta haamuja, vampyyreja tai zombeja tyhjiin ruutuihin (summat ylhäällä). Reunaluku laskee sieltä peilien kautta näkyvät olennot. Zombit näkyvät aina; vampyyrit vain ennen ensimmäistä peiliä, haamut vain sen jälkeen.',
      '空きマスにおばけ・吸血鬼・ゾンビを置きます（合計は上に表示）。端の数字はそこから鏡で反射しながら見える怪物の数。ゾンビは常に見え、吸血鬼は最初の鏡の前だけ、おばけは鏡の後だけ見えます。',
      '빈칸에 유령, 뱀파이어, 좀비를 놓으세요(합계는 위에 표시). 가장자리 숫자는 거기서 거울에 반사되며 보이는 괴물 수입니다. 좀비는 항상, 뱀파이어는 첫 거울 전에만, 유령은 거울 뒤에만 보입니다.',
      '在空格放幽灵、吸血鬼或僵尸（总数显示在上方）。边上的数字是从那里看进去、经镜子反射能看到的怪物数。僵尸总能看到；吸血鬼只在第一面镜子前可见，幽灵只在镜子后可见。',
      'ख़ाली ख़ानों में भूत, पिशाच या ज़ॉम्बी रखें (कुल ऊपर)। किनारे का अंक वहाँ से आईनों में परावर्तित होकर दिखते प्राणी गिनता है। ज़ॉम्बी हमेशा, पिशाच पहले आईने से पहले, भूत केवल उसके बाद दिखता है।',
      'খালি ঘরে ভূত, ভ্যাম্পায়ার বা জম্বি রাখুন (মোট ওপরে)। কিনারার সংখ্যা সেখান থেকে আয়নায় প্রতিফলিত হয়ে দেখা প্রাণী গোনে। জম্বি সবসময়, ভ্যাম্পায়ার প্রথম আয়নার আগে, ভূত কেবল তার পরে দেখা যায়।',
      'Taruh hantu, vampir, atau zombi di sel kosong (total di atas). Angka di tepi = makhluk yang terlihat dari sana lewat pantulan cermin. Zombi selalu terlihat; vampir hanya sebelum cermin pertama, hantu hanya sesudahnya.',
      'Letak hantu, pontianak atau zombi di petak kosong (jumlah di atas). Nombor tepi = makhluk yang nampak dari situ melalui pantulan cermin. Zombi sentiasa nampak; pontianak hanya sebelum cermin pertama, hantu hanya selepasnya.',
      'วางผี แวมไพร์ หรือซอมบี้ในช่องว่าง (ผลรวมอยู่ด้านบน) เลขที่ขอบคือจำนวนสิ่งที่มองเห็นจากตรงนั้นโดยสะท้อนกระจก ซอมบี้เห็นเสมอ แวมไพร์เห็นก่อนกระจกแรกเท่านั้น ผีเห็นหลังกระจกเท่านั้น',
      'Đặt ma, ma cà rồng hoặc thây ma vào ô trống (tổng ở trên). Số ở mép đếm sinh vật nhìn thấy từ đó qua phản chiếu gương. Thây ma luôn thấy; ma cà rồng chỉ trước gương đầu, ma chỉ sau gương.',
      'Maglagay ng multo, bampira o zombie sa bakanteng kahon (nasa itaas ang kabuuan). Binibilang ng numero sa gilid ang nilalang na tanaw mula roon sa repleksiyon ng salamin. Laging tanaw ang zombie; bampira bago lang ang unang salamin, multo pagkatapos lang.',
